#!/usr/bin/env bash
# Generated by gcp-run-guide.html. Read-only discovery; output is not anonymized.
# EXAMPLE: replace PROJECT_ID_1,PROJECT_ID_2 with your own values
# before running it, or generate your own script from gcp-run-guide.html.
set -euo pipefail

# Which repo to use, in order: REPO_DIR if set; the rubrik-sizing-scripts checkout this script sits in;
# the checkout your current folder is in; otherwise ./rubrik-sizing-scripts in the folder you run it from
# (cloned after asking).
TOOL_REL="CLOUD/python/gcp"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]:-$0}")" && pwd)"
if [ -z "${REPO_DIR:-}" ]; then
  for dir in "$SCRIPT_DIR" "$PWD"; do
    TOP="$(git -C "$dir" rev-parse --show-toplevel 2>/dev/null || true)"
    if [ -n "$TOP" ] && [ -d "$TOP/$TOOL_REL" ]; then REPO_DIR="$TOP"; break; fi
  done
  REPO_DIR="${REPO_DIR:-$PWD/rubrik-sizing-scripts}"
fi
if [ ! -d "$REPO_DIR/$TOOL_REL" ]; then
  if [ -n "$(ls -A "$REPO_DIR" 2>/dev/null)" ]; then
    echo "$REPO_DIR exists but has no $TOOL_REL (wrong branch or not rubrik-sizing-scripts?)."
    echo "Switch it to branch master, or set REPO_DIR to another checkout."
    exit 1
  fi
  echo "No rubrik-sizing-scripts checkout found."
  read -r -p "Clone rubrikinc/rubrik-sizing-scripts into $REPO_DIR now (sparse)? [y/N] " clone
  case "$clone" in [yY]*) ;; *) echo "Aborted. Set REPO_DIR to an existing checkout."; exit 1 ;; esac
  git clone --depth 1 --filter=blob:none --sparse --branch master \
    https://github.com/rubrikinc/rubrik-sizing-scripts.git "$REPO_DIR"
  git -C "$REPO_DIR" sparse-checkout set CLOUD
fi
echo "Using repo: $REPO_DIR"
# The output folder; a relative path is taken next to this script.
OUT_DIR="$SCRIPT_DIR"/'output'
cd "$REPO_DIR/$TOOL_REL"

python3 -c 'import sys; sys.exit(0 if sys.version_info >= (3, 10) else 1)' || { echo "Python 3.10 or newer is required."; exit 1; }
python3 -m venv .venv
source .venv/bin/activate
pip install -q -r requirements.txt

gcloud auth application-default print-access-token >/dev/null 2>&1 || { echo "No Application Default Credentials. Run: gcloud auth application-default login"; exit 1; }
echo "Active gcloud account : $(gcloud auth list --filter=status:ACTIVE --format="value(account)" 2>/dev/null | head -1)"
echo "Current gcloud project: $(gcloud config get-value project 2>/dev/null)"
echo "You are about to scan the projects you listed (not necessarily the current one)."
read -r -p "Continue? [y/N] " ans
case "$ans" in [yY]*) ;; *) echo "Aborted."; exit 1 ;; esac

python main.py --projects 'PROJECT_ID_1,PROJECT_ID_2' --output "$OUT_DIR"

ZIP="$(ls -t "$OUT_DIR"/gcp_sizing_results_*.zip 2>/dev/null | head -1 || true)"
if [ -n "$ZIP" ]; then echo "Results: $ZIP (contains project and resource names; keep it local)"; fi
